--[[
    SN_KiciaHook.lua
    ------------------------------------------------------------
    針對 KiciaHook 的包裝載入器，做三件事：
      1) UI 背景：用動漫眼睛圖，ZIndex 卡在背景之上、文字之下
      2) 左上角 KH 文字 → "SN"（保留原字體）
      3) 左上角標題那一整行 → 用 SINSTORS 圖覆蓋（隱藏原文字）
    ------------------------------------------------------------
    兩張圖都內嵌為 base64，執行時透過 writefile + getexecutorasset/getcustomasset 還原。
    用法：loadstring(game:HttpGet("你的_raw_網址"))()
--]]

