-- ===== base64 解碼 =====
local function b64decode(s)
    local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local lookup = {}
    for i = 1, #b do lookup[b:byte(i)] = i - 1 end
    s = s:gsub("[^A-Za-z0-9+/=]", "")
    local out = {}
    local idx = 1
    for i = 1, #s, 4 do
        local c1 = lookup[s:byte(i)] or 0
        local c2 = lookup[s:byte(i+1)] or 0
        local c3 = lookup[s:byte(i+2)] or 0
        local c4 = lookup[s:byte(i+3)] or 0
        local n = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
        local b1 = math.floor(n / 65536) % 256
        local b2 = math.floor(n / 256) % 256
        local b3 = n % 256
        out[idx] = string.char(b1); idx = idx + 1
        if s:sub(i+2, i+2) ~= "=" then
            out[idx] = string.char(b2); idx = idx + 1
        end
        if s:sub(i+3, i+3) ~= "=" then
            out[idx] = string.char(b3); idx = idx + 1
        end
    end
    return table.concat(out)
end

local function assetFromB64(b64, ext)
    local result = "rbxassetid://0"
    pcall(function()
        local bin = b64decode(b64)
        local path = "SN_" .. ext .. "_" .. tostring(math.random(100000, 999999)) .. "." .. ext
        if writefile then
            writefile(path, bin)
            print("[SN_KiciaHook] writefile OK: " .. path)
            if getexecutorasset then
                result = getexecutorasset(path)
                print("[SN_KiciaHook] getexecutorasset → " .. tostring(result))
            end
            if (result == "rbxassetid://0" or result == "" or result == nil) and getcustomasset then
                result = getcustomasset(path)
                print("[SN_KiciaHook] getcustomasset → " .. tostring(result))
            end
        else
            print("[SN_KiciaHook] ⚠️ 執行器不支援 writefile")
        end
    end)
    return result
end

local EYE_IMG = assetFromB64(EYE_B64, "jpg")
local BANNER_IMG = assetFromB64(BANNER_B64, "png")
