-- ===== 2) UI 處理函數 =====
local CG = game:GetService("CoreGui")
local PG = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
local vp = workspace.CurrentCamera.ViewportSize

-- 把動漫眼睛圖插到 Frame（ZIndex 卡在背景之上、文字之下）
local function insertBg(parent)
    if not parent or not parent:IsA("GuiObject") then return end
    if parent:FindFirstChild("SN_BgImage") then
        parent.SN_BgImage.Image = EYE_IMG
        return
    end
    local img = Instance.new("ImageLabel")
    img.Name = "SN_BgImage"
    img.Image = EYE_IMG
    img.BackgroundTransparency = 1
    img.ScaleType = Enum.ScaleType.Crop
    img.Size = UDim2.new(1, 0, 1, 0)
    img.Position = UDim2.new(0, 0, 0, 0)
    local mz = math.huge
    for _, c in ipairs(parent:GetChildren()) do
        if c:IsA("GuiObject") and c.ZIndex < mz then mz = c.ZIndex end
    end
    if mz == math.huge then mz = 0 end
    img.ZIndex = mz + 1
    for _, c in ipairs(parent:GetChildren()) do
        if c ~= img and c:IsA("GuiObject") then
            c.ZIndex = math.max(c.ZIndex, mz + 2)
        end
    end
    img.Parent = parent
end

-- 把 SINSTORS logo 蓋到某個 TextLabel 上（覆蓋整行文字）
local function coverWithTitle(textObj)
    if not textObj or not textObj:IsA("GuiObject") then return end
    if textObj:FindFirstChild("SN_TitleCover") then return end
    local parent = textObj.Parent
    if not parent then return end
    local cov = Instance.new("ImageLabel")
    cov.Name = "SN_TitleCover"
    cov.Image = BANNER_IMG
    cov.BackgroundTransparency = 1
    cov.ScaleType = Enum.ScaleType.Fit
    -- 用與 TextLabel 相同的位置與大小，蓋在它上面
    cov.Size = textObj.Size
    cov.Position = textObj.Position
    cov.AnchorPoint = textObj.AnchorPoint
    cov.Rotation = textObj.Rotation
    -- ZIndex 最高，完全覆蓋文字
    cov.ZIndex = textObj.ZIndex + 10
    -- 隱藏原文字（保留位置/字體資訊不動）
    pcall(function() textObj.TextTransparency = 1 end)
    pcall(function() textObj.TextStrokeTransparency = 1 end)
    cov.Parent = parent
end

-- 文字處理：KH → SN（其他保留）
local function transformText(o)
    local t = o.Text
    if not t or t == "" then return false end
    local trimmed = t:gsub("^%s+", ""):gsub("%s+$", "")
    local lower = trimmed:lower()
    -- 標題（含 Kicia / KiciaHook）：用 SINSTORS 圖覆蓋
    if lower:find("kicia") then
        return true  -- 標記為標題，外層會覆蓋圖
    end
    -- 左上角 KH → SN（精確比對 KH，或 KH 開頭）
    if trimmed:upper() == "KH" then
        pcall(function() o.Text = "SN" end)
    elseif trimmed:upper():match("^KH[%s|%-_/%.]") then
        local rest = trimmed:sub(3)
        pcall(function() o.Text = "SN" .. rest end)
    end
    return false
end

local processed = {}
local titleCovered = {}
local function processGui(root)
    if not root then return end
    for _, o in ipairs(root:GetDescendants()) do
        if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
            -- 1) 文字處理 + 標題覆蓋
            local isTitle = false
            pcall(function() isTitle = transformText(o) end)
            if isTitle and not titleCovered[o] then
                titleCovered[o] = true
                pcall(coverWithTitle, o)
            end
            -- 2) 含文字的 Frame → 插動漫眼睛背景圖
            local t = o.Text
            if t and t ~= "" then
                local p = o.Parent
                if p and p:IsA("Frame") and not processed[p] then
                    local sz = p.AbsoluteSize
                    if sz.X < vp.X * 0.95 and sz.Y < vp.Y * 0.95 and sz.X > 60 and sz.Y > 30 then
                        -- 不要在標題覆蓋過的 Frame 上再插背景（會跟 SINSTORS logo 重疊）
                        local hasTitle = false
                        for _, c in ipairs(p:GetChildren()) do
                            if (c:IsA("TextLabel") or c:IsA("TextButton")) and c.Text and c.Text:lower():find("kicia") then
                                hasTitle = true; break
                            end
                        end
                        if not hasTitle then
                            processed[p] = true
                            pcall(insertBg, p)
                        end
                    end
                end
            end
        end
    end
end

-- ===== 3) 持續掃描（每 0.3 秒）=====
local scanCount = 0
task.spawn(function()
    while true do
        pcall(function()
            for _, p in ipairs({CG, PG}) do
                for _, c in ipairs(p:GetChildren()) do
                    if c:IsA("ScreenGui") then
                        processGui(c)
                    end
                end
            end
        end)
        scanCount = scanCount + 1
        if scanCount == 1 or scanCount % 10 == 0 then
            print("[SN_KiciaHook] 掃描 #" .. scanCount .. " EYE=" .. EYE_IMG .. " BANNER=" .. BANNER_IMG)
        end
        task.wait(0.3)
    end
end)

print("[SN_KiciaHook] 啟動持續掃描器（每 0.3 秒）")
